import 'package:flutter/material.dart'; import 'package:flutter_riverpod/flutter_riverpod.dart';
import '../data/people_repository.dart';
final peopleRepositoryProvider = Provider<PeopleRepository>((ref) => throw UnimplementedError());
final peopleProvider = FutureProvider.family<PeoplePage, String>((ref, query) => ref.watch(peopleRepositoryProvider).page(query: query));
class PeopleScreen extends ConsumerStatefulWidget { const PeopleScreen({super.key}); @override ConsumerState<PeopleScreen> createState() => _PeopleScreenState(); }
class _PeopleScreenState extends ConsumerState<PeopleScreen> { String query = ''; String gender = ''; @override Widget build(BuildContext context) { final state = ref.watch(peopleProvider(query)); return Column(children:[Padding(padding:const EdgeInsets.all(12),child:TextField(onChanged:(v){Future<void>.delayed(const Duration(milliseconds:400),(){if(mounted)setState(()=>query=v);});},decoration:const InputDecoration(prefixIcon:Icon(Icons.search),labelText:'Buscar personagem',border:OutlineInputBorder()))), DropdownButton<String>(value:gender,items:const [DropdownMenuItem(value:'',child:Text('Todos os gêneros')),DropdownMenuItem(value:'male',child:Text('Masculino')),DropdownMenuItem(value:'female',child:Text('Feminino')),DropdownMenuItem(value:'unknown',child:Text('Desconhecido'))],onChanged:(v)=>setState(()=>gender=v??'')), Expanded(child:state.when(loading:()=>const Center(child:CircularProgressIndicator()),error:(e,_)=>Center(child:Text('$e')),data:(page){final people=page.people.where((p)=>gender.isEmpty||p.gender==gender).toList(); return ListView.builder(itemCount:people.length,itemBuilder:(c,i){final p=people[i];return ListTile(leading:CircleAvatar(child:Text(p.name.substring(0,1))),title:Text(p.name),subtitle:Text('${p.gender} · ${p.birthYear}'),onTap:()=>Navigator.push(c,MaterialPageRoute<void>(builder:(_)=>PersonDetail(person:p))));});}))]);} }
class PersonDetail extends StatelessWidget { const PersonDetail({super.key,required this.person}); final dynamic person; @override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text(person.name)),body:ListView(padding:const EdgeInsets.all(20),children:[Text('Nascimento: ${person.birthYear}'),Text('Gênero: ${person.gender}'),Text('Filmes: ${person.filmUrls.length}'),Text('Espécies: ${person.speciesUrls.length}') ])); }
